parameters.jsCode:
const body = $input.first().json.body;
const required = ['episode_title', 'transcript_or_notes'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.transcript_or_notes.trim().length < 100) return [{ json: { valid: false, error: 'transcript_or_notes too short' } }];
const outputFormats = ['show_notes', 'newsletter_feature', 'social_pack', 'all'];
const outputFormat = outputFormats.includes(body.output_format) ? body.output_format : 'all';
return [{ json: {
  valid: true,
  podcastName: body.podcast_name || '',
  episodeTitle: body.episode_title.trim(),
  episodeNumber: body.episode_number || '',
  guestName: body.guest_name || '',
  guestTitle: body.guest_title || '',
  hostName: body.host_name || '',
  transcriptOrNotes: body.transcript_or_notes.trim().slice(0, 12000),
  outputFormat,
  targetAudience: body.target_audience || '',
  tone: body.tone || 'conversational',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

values.content:
Process this podcast episode and generate content assets.

Podcast: {{ $json.podcastName || 'not specified' }}
Episode: {{ $json.episodeNumber ? '#' + $json.episodeNumber + ' — ' : '' }}{{ $json.episodeTitle }}
Guest: {{ $json.guestName ? $json.guestName + (($json.guestTitle) ? ', ' + $json.guestTitle : '') : 'no guest (solo episode)' }}
Host: {{ $json.hostName || 'not specified' }}
Audience: {{ $json.targetAudience || 'general' }}
Tone: {{ $json.tone }}
Output format: {{ $json.outputFormat }}

Transcript / notes:
{{ $json.transcriptOrNotes }}

Return this JSON:
{
  "episode_summary": "3-4 sentences capturing what was covered and the key takeaway — specific to this episode",
  "key_insights": [
    {"insight": "specific insight or idea from the episode", "context": "brief context or quote paraphrase that supports it"}
  ],
  "timestamps_suggested": [
    {"topic": "topic or segment name", "description": "what's covered in this segment"}
  ],
  "show_notes": {
    "intro_paragraph": "2-3 sentences that sell the episode — makes someone want to listen",
    "what_you_ll_learn": ["specific learning or takeaway — bullet point style"],
    "episode_highlights": ["3-5 notable moments, quotes, or topics from the episode"],
    "resources_mentioned": ["any books, tools, people, or links mentioned in the transcript"],
    "about_the_guest": "1-2 sentences about the guest if there is one, else null"
  },
  "newsletter_feature": {
    "subject_line": "email subject if featuring this episode in a newsletter",
    "body": "150-200 word feature — conversational, gives enough value that the reader feels they got something even without listening, but makes them want to hear more"
  },
  "social_pack": {
    "twitter_thread_opener": "opening tweet for a thread about this episode — hook that earns the next click",
    "linkedin_post": "200-250 word LinkedIn post — insight-led, ends with a question or reflection",
    "instagram_caption": "caption for a quote card or audiogram — under 150 words, hashtag suggestions at end",
    "pull_quote": "the single most shareable quote or insight from the episode — verbatim if transcript, paraphrased if notes"
  }
}

