try { assets = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
assets._meta = { podcastName: input.podcastName, episodeTitle: input.episodeTitle, episodeNumber: input.episodeNumber, guestName: input.guestName, replyEmail: input.replyEmail, outputFormat: input.outputFormat };
return [{ json: assets }];

